/// </summary>
[ExtensionOf(classStr(ReturnAcknowledgmentAndDocumentDP))]
final class AVAReturnAcknowledgmentAndDocumentDPCls_Extension
{
    public BarcodeSetup clsBarcodeSetup;
    public Barcode      clsBarcode;

}

Method.Source:
/// <summary>
///     Initializes a bar-code object according to the setup in the <c>InventParameters</c> table.
/// </summary>
private void avaInitBarcode()
{
    BarcodeSetupId  locBarcodeSetupId;

    locBarcodeSetupId   = WHSParameters::find().BarcodeSetupId;
    clsBarcodeSetup     = BarcodeSetup::find(locBarcodeSetupId);
    clsBarcode          = clsBarcodeSetup.barcode();
}

/// <summary>
///     AVA <c>avaBarCodeStrReturnItemNum</c> method.
/// </summary>
/// <param name="_returnItemNum">
///     <c>SalesReturnItemNum</c> as type
/// </param>
/// <param name="_validate">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>container</c> as return value
/// </returns>
private container avaBarCodeStrReturnItemNum(SalesReturnItemNum _returnItemNum, boolean _validate = true)
{
    BarCodeString   retVal1;
    BarCodeString   retVal2;

    BarCodeString   locBarcodeContent;

    locBarcodeContent = strUpr(_returnItemNum);

    if (!locBarcodeContent || clsBarcode == null)
    {
        return [retVal1, retVal2];
    }

    if(_validate)
    {
        if (clsBarcodeSetup.validateBarcode(locBarcodeContent))
        {
            clsBarcode.string(true, locBarcodeContent);
            clsBarcode.encode();
        }
        else
        {
            throw(error(strFmt("@SYS41409", clsBarcode.barcodeType(), locBarcodeContent)));
        }
    }
    else
    {
        clsBarcode.string(true, locBarcodeContent);
        clsBarcode.encode();
    }
    if (!clsBarcode)
    {
        return [retVal1, retVal2];
    }
    retVal1 = clsBarcode.barcodeStr();
    retVal2 = clsBarcode.barcodeStrHR();

    return [retVal1, retVal2];
}

/// <summary>
///     AVA <c>avaBarCodeStrItemId</c> method.
/// </summary>
/// <param name="_itemId">
///     <c>ItemId</c> as type
/// </param>
/// <param name="_validate">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>container</c> as return value
/// </returns>
private container avaBarCodeStrItemId(ItemId _itemId, boolean _validate = true)
{
    BarCodeString   retVal1;
    BarCodeString   retVal2;

    BarCodeString   locBarcodeContent;

    locBarcodeContent = strUpr(_itemId);

    if (!locBarcodeContent || clsBarcode == null)
    {
        return [retVal1, retVal2];
    }

    if(_validate)
    {
        if (clsBarcodeSetup.validateBarcode(locBarcodeContent))
        {
            clsBarcode.string(true, locBarcodeContent);
            clsBarcode.encode();
        }
        else
        {
            throw(error(strFmt("@SYS41409", clsBarcode.barcodeType(), locBarcodeContent)));
        }
    }
    else
    {
        clsBarcode.string(true, locBarcodeContent);
        clsBarcode.encode();
    }
    if (!clsBarcode)
    {
        return [retVal1, retVal2];
    }

    retVal1 = clsBarcode.barcodeStr();
    retVal2 = clsBarcode.barcodeStrHR();

    return [retVal1, retVal2];
}

/// <summary>
///     Creates report data for the return acknowledgment and return document.
/// </summary>
protected void createReportData()
{
    /* reactivate if barcodes needed
    this.avaInitBarcode();
    */
    next createReportData();
}

/// <summary>
///     Initializes the template used to create the return acknowledgment and return document lines.
/// </summary>
/// <returns>
///     The initialized template.
/// </returns>
protected ReturnAcknowledgmentAndDocumentTmp initReturnAcknowledgmentAndDocTemplate()
{
    ReturnAcknowledgmentAndDocumentTmp retVal;

    retVal = next initReturnAcknowledgmentAndDocTemplate();

    retVal.AVAReturnItemNumBarcodeFontName      = clsBarcodeSetup.fontName;
    retVal.AVAReturnItemNumBarcodeFontSize      = clsBarcodeSetup.fontSize;
    [   retVal.AVAReturnItemNumBarcodeStr,
        retVal.AVAReturnItemNumBarcodeStrHR ]   = this.avaBarCodeStrReturnItemNum(retVal.ReturnItemNum);
    retVal.AVAReturnItemNum2DCodeBitmap         = this.generateQRCode(retVal.ReturnItemNum);

    return retVal;
}

/// <summary>
///     Initializes a return acknowledgment and return document line.
/// </summary>
/// <param name = "_returnAcknowledgmentAndDocumentTemplate">
///     The template used to initialize the line.
/// </param>
/// <returns>
///     The initialized line.
/// </returns>
protected ReturnAcknowledgmentAndDocumentTmp initReturnAcknowledgmentAndDocLine(ReturnAcknowledgmentAndDocumentTmp _returnAcknowledgmentAndDocumentTemplate)
{
    ReturnAcknowledgmentAndDocumentTmp retVal;

    retVal = next initReturnAcknowledgmentAndDocLine(_returnAcknowledgmentAndDocumentTemplate);

    retVal.AVAItemIdBarcodeFontName         = clsBarcodeSetup.fontName;
    retVal.AVAItemIdBarcodeFontSize         = clsBarcodeSetup.fontSize;
    [   retVal.AVAItemIdBarcodeStr,
        retVal.AVAItemIdBarcodeStrHR    ]   = this.avaBarCodeStrItemId(retVal.ItemId);
    if(!salesLine.AVAItemSet)
    {
        retVal.AVAItemId2DCodeBitmap    = this.generateQRCode(retVal.ItemId);
    }

    return retVal;
}

